insert into public.card_definitions (id, deck, title, body, effect) values
  ('ch01', 'chance', 'Richiamo alla Fontana', 'Un incantesimo di ritorno ti riporta alla Fontana della Rinascita. Ritira il bonus.', '{"type":"moveTo","to":"start"}'::jsonb),
  ('ch02', 'chance', 'Udienza a corte', 'Il sovrano di Argentea ti convoca: avanza fino al Palazzo Reale d''Argento.', '{"type":"moveTo","to":"palazzo-reale"}'::jsonb),
  ('ch03', 'chance', 'Pellegrinaggio spirituale', 'Avanza fino al Tempio del Vento. Se passi dalla Fontana della Rinascita ritira il bonus.', '{"type":"moveTo","to":"tempio-vento"}'::jsonb),
  ('ch04', 'chance', 'Miraggio nel deserto', 'Avanza fino all''Oasi Nascosta. Se passi dalla Fontana della Rinascita ritira il bonus.', '{"type":"moveTo","to":"oasi"}'::jsonb),
  ('ch05', 'chance', 'Varco instabile', 'Un varco ti risucchia fino al trasporto più vicino. Se ha un padrone, paghi il doppio del pedaggio.', '{"type":"moveToNearest","kind":"transport"}'::jsonb),
  ('ch06', 'chance', 'Ritirata strategica', 'Raggiungi il trasporto più vicino. Se ha un padrone, paghi il doppio del pedaggio.', '{"type":"moveToNearest","kind":"transport"}'::jsonb),
  ('ch07', 'chance', 'Sete di mana', 'Raggiungi la fonte arcana più vicina. Se ha un padrone, paghi 10 volte il risultato dei dadi.', '{"type":"moveToNearest","kind":"utility"}'::jsonb),
  ('ch08', 'chance', 'Imboscata nella giungla', 'Una creatura selvaggia ti sbarra la strada: torna indietro di 3 caselle.', '{"type":"moveBy","steps":-3}'::jsonb),
  ('ch09', 'chance', 'Sentiero segreto', 'Uno scout ti mostra una scorciatoia: avanza di 4 caselle.', '{"type":"moveBy","steps":4}'::jsonb),
  ('ch10', 'chance', 'Agguato della guardia reale', 'Vieni catturato: vai direttamente nelle Segrete del Re senza passare dalla Fontana.', '{"type":"goToJail"}'::jsonb),
  ('ch11', 'chance', 'Pergamena d''evasione', 'Esci gratis dalle Segrete. Conserva questa carta finché non la usi o la scambi.', '{"type":"jailFree"}'::jsonb),
  ('ch12', 'chance', 'Bottino del drago', 'Il tuo gruppo abbatte un drago antico: ricevi 150 crediti.', '{"type":"money","amount":150}'::jsonb),
  ('ch13', 'chance', 'Campione del torneo', 'Vinci il torneo dei campioni: ricevi 100 crediti.', '{"type":"money","amount":100}'::jsonb),
  ('ch14', 'chance', 'Pedaggio del ponte', 'Il guardiano del ponte pretende il suo obolo: paga 30 crediti.', '{"type":"money","amount":-30}'::jsonb),
  ('ch15', 'chance', 'Pozione esplosa', 'Un esperimento alchemico finisce male: paga 120 crediti di danni.', '{"type":"money","amount":-120}'::jsonb),
  ('ch16', 'chance', 'Assedio alle mura', 'Ripara le difese: paga 30 crediti per ogni torretta e 120 per ogni fortezza.', '{"type":"repairs","perHouse":30,"perTower":120}'::jsonb),
  ('ch17', 'chance', 'Capitano della spedizione', 'Guidi la spedizione e paghi le provviste: versa 40 crediti a ogni giocatore.', '{"type":"payEach","amount":40}'::jsonb),
  ('ch18', 'chance', 'Viaggio carovaniero', 'Avanza fino alla Carovana delle Dune. Se passi dalla Fontana della Rinascita ritira il bonus.', '{"type":"moveTo","to":"carovana"}'::jsonb),
  ('ch19', 'chance', 'Reliquia venduta', 'Un collezionista compra una tua reliquia: ricevi 60 crediti.', '{"type":"money","amount":60}'::jsonb),
  ('ch20', 'chance', 'Banchetto dei mercenari', 'Offri da bere ai mercenari: paga 50 crediti.', '{"type":"money","amount":-50}'::jsonb),
  ('ch21', 'chance', 'Consiglio di guerra', 'Il generale ti attende: avanza fino al Bastione del Generale.', '{"type":"moveTo","to":"bastione"}'::jsonb),
  ('ch22', 'chance', 'Nebbia magica', 'Ti perdi nella nebbia: torna indietro di 2 caselle.', '{"type":"moveBy","steps":-2}'::jsonb),
  ('co01', 'community', 'Errore del tesoriere', 'Il tesoriere della gilda sbaglia i conti a tuo favore: ricevi 200 crediti.', '{"type":"money","amount":200}'::jsonb),
  ('co02', 'community', 'Guaritore del villaggio', 'Paga 60 crediti per le cure dopo l''ultima battaglia.', '{"type":"money","amount":-60}'::jsonb),
  ('co03', 'community', 'Eredità del mentore', 'Il tuo vecchio maestro ti lascia 100 crediti.', '{"type":"money","amount":100}'::jsonb),
  ('co04', 'community', 'Fiera della gilda', 'Le tue merci vanno a ruba alla fiera: ricevi 50 crediti.', '{"type":"money","amount":50}'::jsonb),
  ('co05', 'community', 'Grazia del sovrano', 'Esci gratis dalle Segrete. Conserva questa carta finché non la usi o la scambi.', '{"type":"jailFree"}'::jsonb),
  ('co06', 'community', 'Accusa di tradimento', 'Vai direttamente nelle Segrete del Re senza passare dalla Fontana della Rinascita.', '{"type":"goToJail"}'::jsonb),
  ('co07', 'community', 'Rinascita', 'Torni alla Fontana della Rinascita: ritira il bonus.', '{"type":"moveTo","to":"start"}'::jsonb),
  ('co08', 'community', 'Festa del raccolto', 'Organizzi la festa: ogni giocatore ti versa 25 crediti.', '{"type":"collectFromEach","amount":25}'::jsonb),
  ('co09', 'community', 'Anniversario della gilda', 'È la tua festa: ogni giocatore ti regala 50 crediti.', '{"type":"collectFromEach","amount":50}'::jsonb),
  ('co10', 'community', 'Addestramento all''accademia', 'Paga 100 crediti per il corso di scherma.', '{"type":"money","amount":-100}'::jsonb),
  ('co11', 'community', 'Mappa venduta', 'Vendi una mappa dei sentieri della giungla: ricevi 25 crediti.', '{"type":"money","amount":25}'::jsonb),
  ('co12', 'community', 'Rinforzo delle difese', 'Paga 40 crediti per ogni torretta e 115 per ogni fortezza.', '{"type":"repairs","perHouse":40,"perTower":115}'::jsonb),
  ('co13', 'community', 'Rimborso della corona', 'La corona ti rimborsa le spese di guerra: ricevi 120 crediti.', '{"type":"money","amount":120}'::jsonb),
  ('co14', 'community', 'Quota della gilda', 'Paga 50 crediti di quota annuale alla gilda.', '{"type":"money","amount":-50}'::jsonb),
  ('co15', 'community', 'Torneo di tiro con l''arco', 'Arrivi secondo al torneo: ricevi 10 crediti.', '{"type":"money","amount":10}'::jsonb),
  ('co16', 'community', 'Dividendi della carovana', 'I commerci della carovana rendono bene: ricevi 80 crediti.', '{"type":"money","amount":80}'::jsonb),
  ('co17', 'community', 'Visita ai prigionieri', 'Porti viveri ai prigionieri: spostati sulle Segrete del Re (solo in visita).', '{"type":"moveTo","to":"jail"}'::jsonb),
  ('co18', 'community', 'Armatura da riforgiare', 'Paga 150 crediti al fabbro per l''armatura nuova.', '{"type":"money","amount":-150}'::jsonb),
  ('co19', 'community', 'Benedizione degli spiriti', 'Gli spiriti dell''isola ti premiano: ricevi 150 crediti.', '{"type":"money","amount":150}'::jsonb),
  ('co20', 'community', 'Strada sbarrata', 'Una frana blocca il passo: torna indietro di 2 caselle.', '{"type":"moveBy","steps":-2}'::jsonb),
  ('co21', 'community', 'Cristallo di mana trovato', 'Trovi un piccolo cristallo di mana: ricevi 30 crediti.', '{"type":"money","amount":30}'::jsonb),
  ('co22', 'community', 'Giro di birre in taverna', 'Offri da bere a tutti: paga 20 crediti a ogni giocatore.', '{"type":"payEach","amount":20}'::jsonb)
on conflict (id) do update set deck = excluded.deck, title = excluded.title, body = excluded.body, effect = excluded.effect;
